def is_valid_shoe(shoe):
    """Check if the shoe is a valid shoe representation."""
    shoe_type, shoe_size = shoe
    return isinstance(shoe_type, int) and isinstance(shoe_size, int) and shoe_type in (0, 1) and shoe_size > 0

def count_shoes_by_size(shoes):
    """Count the number of left and right shoes for each size."""
    left_shoes = {}
    right_shoes = {}
    for shoe_type, shoe_size in shoes:
        if shoe_type == 0:
            left_shoes[shoe_size] = left_shoes.get(shoe_size, 0) + 1
        else:
            right_shoes[shoe_size] = right_shoes.get(shoe_size, 0) + 1
    return left_shoes, right_shoes

def can_pair_shoes(left_shoes, right_shoes):
    """Check if it is possible to pair the shoes based on size counts."""
    for size in left_shoes:
        if size not in right_shoes or left_shoes[size] != right_shoes[size]:
            return False
    return True

def pair_of_shoes(shoes):
    """Check if it is possible to pair the shoes."""
    if not all(is_valid_shoe(shoe) for shoe in shoes):
        raise ValueError("Invalid shoe representation")
    left_shoes, right_shoes = count_shoes_by_size(shoes)
    return can_pair_shoes(left_shoes, right_shoes)
